/* Explicit escalation recipients and accountable follow-up. Owner stays with the AO. */
let escalationFilter='Aktif';
const escCall=(fn,...args)=>fn+'('+args.map(x=>E(JSON.stringify(x))).join(',')+')';
function escRows(){return (db.notifications||[]).filter(n=>n.escalation)}
function escStatus(n){return n.resolved?(n.workflow?.status==='Selesai'?'Selesai':'Pemicu teratasi'):n.workflow?.status==='Selesai'?'Perlu tindak lanjut ulang':n.workflow?.status||'Belum ditangani'}
function escSource(n){return ({lead:db.leads,opportunity:db.opps,task:db.tasks,approval:db.tasks}[n.kind]||[]).find(x=>x.id===n.record)}
function escOpenSource(id){const n=(db.notifications||[]).find(x=>x.id===id);if(!n)return;document.querySelector('#modal')?.close();go(({lead:'Lead detail',opportunity:'Opportunity detail',approval:'Persetujuan'}[n.kind]||'Aktivitas detail'),n.record)}
function escCard(n){return '<button class="esc-row" onclick="'+escCall('escDetail',n.id)+'"><span><strong>'+E(n.title)+'</strong><small>'+E(n.note)+' · AO: '+E(n.owner||'Belum ditetapkan')+' · '+E(n.branch||'Cabang belum diisi')+'</small><small>Penerima: '+E((n.recipientNames||[]).join(', ')||'Belum tersedia')+' · '+E(n.lateDays??'—')+' hari melewati batas</small></span><span class="esc-status '+(!n.resolved&&escStatus(n)==='Belum ditangani'?'esc-warning':'')+'">'+E(escStatus(n))+'</span></button>'}
function escDashboard(){const all=escRows().filter(n=>!n.resolved&&(!dashboardOwner||n.owner===dashboardOwner)),pending=all.filter(n=>escStatus(n)==='Belum ditangani');return '<section class="dash-panel esc-dashboard"><div class="dash-panel-head"><div><h2>Eskalasi perlu perhatian <span class="esc-count">'+all.length+'</span></h2><p>'+pending.length+' belum ditangani · Posisi SLA saat ini; filter periode tidak membatasi alert aktif. Owner tetap AO.</p></div>'+btn('Lihat semua',"go('Notifikasi')")+'</div>'+(all.slice().sort((a,b)=>(b.lateDays||0)-(a.lateDays||0)).slice(0,5).map(escCard).join('')||empty('Tidak ada eskalasi aktif untuk akun / filter AO ini.'))+'</section>'}
const escOldDashboard=comprehensiveDashboard;
comprehensiveDashboard=function(){return escOldDashboard()+escDashboard()};
scaleNotifications=function(){const items=db.notifications||[],es=items.filter(n=>n.escalation),filtered=es.filter(n=>escalationFilter==='Semua'||escalationFilter==='Aktif'&&!n.resolved||escalationFilter==='Belum ditangani'&&!n.resolved&&escStatus(n)==='Belum ditangani'||escalationFilter==='Riwayat'&&n.resolved);return titleBlock('Notifikasi & Eskalasi','Eskalasi ditujukan ke SPV yang dipetakan; tanpa mapping diteruskan ke Superadmin. Pemilik record tetap AO.')+'<div class="tabs">'+['Aktif','Belum ditangani','Riwayat','Semua'].map(f=>btn(f,escCall('escFilter',f),f===escalationFilter)).join('')+'</div>'+detailPanel('Eskalasi · '+filtered.length,filtered.map(escCard).join('')||empty('Tidak ada eskalasi pada filter ini.'))+detailPanel('Reminder lainnya',items.filter(n=>!n.escalation&&!n.resolved).map(n=>'<button class="esc-row" onclick="'+escCall('escOpenSource',n.id)+'"><span><strong>'+E(n.title)+'</strong><small>'+E(n.note)+' · '+E(n.owner)+'</small></span><span>↗</span></button>').join('')||empty('Tidak ada reminder aktif.'))+'<p class="hint">Notifikasi in-app diperbarui saat CMS terbuka (sekitar 5 detik, saat tidak mengisi form). Belum mengirim email / push ketika aplikasi ditutup. Riwayat aturan lama hanya terlihat Superadmin.</p>'};
function escFilter(f){escalationFilter=f;renderContent()}
function escDetail(id){const n=(db.notifications||[]).find(x=>x.id===id);if(!n)return;const wf=n.workflow||{status:'Belum ditangani',history:[]};const history=wf.history.map(h=>'<li><b>'+E(h.status)+'</b> · '+E(h.by)+' · '+E(fmt(h.at))+'<p>'+E(h.note)+'</p></li>').join('');const can=n.canRespond&&!journey;modal('Detail eskalasi',detailFacts([['Record',n.note],['Jenis',({lead:'Lead',opportunity:'Opportunity',task:'Task',approval:'Persetujuan'})[n.kind]||n.kind],['AO penanggung jawab',n.owner],['Cabang',n.branch||'Belum diisi'],['Penerima',(n.recipientNames||[]).join(', ')||'Belum tersedia'],['Routing',n.routing||'Aturan lama'],['Batas waktu',n.deadline?fmt(n.deadline):'—'],['Keterlambatan',String(n.lateDays??'—')+' hari'],['Kondisi SLA',n.resolved?'Pemicu sudah teratasi':'Masih melewati batas'],['Tindak lanjut',escStatus(n)]])+'<div class="actions">'+btn('Buka record',escCall('escOpenSource',id))+(can&&!n.resolved?btn('Buat Task tindak lanjut',escCall('escCreateTask',id)):'')+'</div><h3>Riwayat tindak lanjut</h3><ol class="esc-history">'+(history||'<li>Belum ada respons SPV.</li>')+'</ol>'+(n.resolved?'<p class="hint">Sistem mendeteksi pemicu sudah teratasi. Catat hasil penyelesaian untuk menutup tindak lanjut.</p>':'<p class="hint">Memberi arahan tidak menghilangkan keterlambatan. Atasi penyebab pada record asal sebelum menutup eskalasi.</p>')+(can?select('Tindak lanjut','status',n.resolved?['Selesai']:['Diterima','Dalam tindak lanjut'],n.resolved?'Selesai':wf.status==='Dalam tindak lanjut'?'Dalam tindak lanjut':'Diterima')+area('Arahan / hasil tindak lanjut','note','',true):'<p class="hint">Hanya SPV penerima dan Superadmin yang dapat mencatat tindak lanjut.</p>'),f=>{if(!can)return false;const button=document.querySelector('#form button.primary');button.disabled=true;api('escalation',{episode:n.episode,revision:wf.revision||0,status:f.status,note:f.note}).then(async()=>{document.querySelector('#modal').close();applyServer(await api('state'));toast('Tindak lanjut eskalasi tersimpan')}).catch(e=>{document.querySelector('#formerror').textContent=e.message;button.disabled=false});return false});if(!can)document.querySelector('#form button.primary').hidden=true;}
function escCreateTask(id){const n=(db.notifications||[]).find(x=>x.id===id),source=n&&escSource(n);if(!source||!n.canRespond)return toast('Record tidak tersedia.');document.querySelector('#modal').close();newTask(source.profile,n.kind==='opportunity'?source.id:source.opp||'',n.kind==='lead'?source.id:source.lead||'');const form=document.querySelector('#form');if(form?.elements.owner){const candidate=[n.owner,source.owner].find(name=>Array.from(form.elements.owner.options).some(o=>o.value===name));if(candidate)form.elements.owner.value=candidate;}if(form?.elements.purpose)form.elements.purpose.value='Tindak lanjut eskalasi: '+n.note;}
const escOldConfig=configScreenConnected;
configScreenConnected=function(){const html=escOldConfig();if(configTab!=='escalation'||authUser.role!=='Superadmin')return html;const e=masters().escalation,name=id=>memberList.find(m=>m.id===id)?.name||id;const rows=[...(e.aoRoutes||[]).map(r=>['AO: '+name(r.aoId),name(r.spvId)]),...(e.branchRoutes||[]).map(r=>['Cabang: '+r.branch,name(r.spvId)])];return html+detailPanel('Mapping penerima eskalasi','<p>Prioritas: mapping AO → mapping cabang → Superadmin. Jika penerima aturan adalah Superadmin, seluruh eskalasi langsung ke Superadmin. SPV lain tidak menerima alert ini.</p>'+detailFacts(rows.length?rows:[['Mapping','Belum diatur; fallback ke Superadmin']])+btn('Atur mapping SPV','escRoutingForm()',true))};
function escRoutingForm(){const e=masters().escalation,choices=[['','Fallback cabang / Superadmin'],...memberList.filter(m=>m.role==='SPV'&&m.active!==false).map(m=>[m.id,m.name])],aos=memberList.filter(m=>m.role==='AO'&&m.active!==false),branches=leadPolicy().branches;modal('Mapping AO / cabang → SPV','<p>Mapping AO lebih diprioritaskan daripada cabang. Kosongkan untuk fallback. Tidak mengubah akses modul atau owner.</p><h3>Per AO</h3>'+aos.map((a,i)=>leadChoice(a.name,'ao'+i,choices,e.aoRoutes?.find(r=>r.aoId===a.id)?.spvId||'')).join('')+'<h3>Fallback per cabang</h3>'+branches.map((b,i)=>leadChoice(b,'branch'+i,choices,e.branchRoutes?.find(r=>r.branch===b)?.spvId||'')).join(''),f=>{const config=clone(db.config);config.masters.escalation={...e,aoRoutes:aos.flatMap((a,i)=>f['ao'+i]?[{aoId:a.id,spvId:f['ao'+i]}]:[]),branchRoutes:branches.flatMap((b,i)=>f['branch'+i]?[{branch:b,spvId:f['branch'+i]}]:[])};saveMasters(config,'new')})}
const escOldRender=renderContent;
renderContent=function(){escOldRender();if(!authUser||journey)return;let b=document.querySelector('#escHeader');if(!b){b=document.createElement('button');b.id='escHeader';b.className='esc-header';b.onclick=()=>go('Notifikasi');document.querySelector('header .user')?.prepend(b)}const count=escRows().filter(n=>!n.resolved&&escStatus(n)==='Belum ditangani').length;const total=escRows().filter(n=>!n.resolved).length;b.textContent='Eskalasi '+total+(count?' · '+count+' baru':'');b.setAttribute('aria-label',total+' eskalasi aktif, '+count+' belum ditangani');b.classList.toggle('esc-warning',count>0);if(view==='Monitoring'){const p=document.querySelector('.esc-dashboard'),first=document.querySelector('#app');if(p&&first)first.prepend(p)}};
